# %% ../nbs/api/lgssystem.ipynb #a1dd7fc3
class ScipyGCROTMKSpILUSolver(Solver):

    # @defaults('tol', 'maxiter', 'spilu_drop_tol', 'spilu_fill_factor', 'spilu_drop_rule', 'spilu_permc_spec')
    # @defaults('check_finite')
    def __init__(self, check_finite=None, atol=0., rtol=1e-5, maxiter=1000, gcrotmk_m=20,
                 spilu_drop_tol=1e-4, spilu_fill_factor=20, spilu_drop_rule=None, spilu_permc_spec='COLAMD', preconditioner=None, preconditioner_block_size=None):
        super().__init__()
        self.__auto_init(locals())

    def _solve(self, operator, V, mu, initial_guess):
        operator = operator.assemble(mu)
        matrix = to_matrix(operator).tocsc()
        precond = to_matrix(self.preconditioner.assemble(mu)).tocsc() if self.preconditioner else matrix
        block_size = self.preconditioner_block_size or precond.shape[0]
        n_blocks = precond.shape[0] // block_size
            
        V = V.to_numpy()
        initial_guess = initial_guess.to_numpy() if initial_guess is not None else None
        promoted_type = np.promote_types(matrix.dtype, V.dtype)

        logger.info(f'Solving {V.shape[1]} linear systems of size {matrix.shape[0]} with block size {block_size} and {n_blocks} blocks using gcrotmk (m={self.gcrotmk_m}) with spilu (drop_tol={self.spilu_drop_tol}, fill_factor={self.spilu_fill_factor}) preconditioner')

        tic = clock()
        R = np.empty((matrix.shape[1], V.shape[1]), dtype=promoted_type, order='F')
        ilu = [spilu(precond[i:i+block_size, i:i+block_size], drop_tol=self.spilu_drop_tol, fill_factor=self.spilu_fill_factor,
            drop_rule=self.spilu_drop_rule, permc_spec=self.spilu_permc_spec) for i in range(0, precond.shape[0], block_size)]
        
        logger.info(f'Preconditioner setup completed in {clock() - tic:.2f} seconds')

        n_solves = 0
        n_iterations = 0

        def ilu_block_solve(v):
            v = v.reshape(n_blocks, block_size)
            result = np.empty_like(v).astype(matrix.dtype)
            for i in range(n_blocks):
                result[i] = ilu[i].solve(v[i])
            nonlocal n_solves
            n_solves += 1
            return result.reshape(-1)
        
        precond = LinearOperator(matrix.shape, ilu_block_solve)

        def callback(xk):
            nonlocal n_iterations
            n_iterations += 1

        for i in range(V.shape[1]):
            tic = clock()
            n_iterations = 0
            n_solves = 0
            R[:, i], info = gcrotmk(matrix, V[:, i], initial_guess[:, i] if initial_guess is not None else None,
                                     atol=self.atol, rtol=self.rtol, maxiter=self.maxiter, M=precond, m=self.gcrotmk_m, callback=callback)
            if info != 0:
                if info > 0:
                    raise InversionError(f'gcrotmk failed to converge after {info} iterations')
                else:
                    raise InversionError(f'gcrotmk failed with error code {info} (illegal input or breakdown)')

            logger.info(f'gcrotmk converged in {n_iterations} iterations for vector {i+1}/{V.shape[1]}, with {n_solves} preconditioner solves in {clock() - tic:.2f} seconds')

        if self.check_finite:
            if not np.isfinite(np.sum(R)):
                raise InversionError('Result contains non-finite values')

        return operator.source.from_numpy(R), {}

# %% ../nbs/api/lgssystem.ipynb #70ebc7a8
class LGSSystem(ParametricObject):
    """`LGSSystem` creates numerical models for the chosen laser guide star atomic system."""
    
    block_names = [
        "A_ind", # Part of density-matrix evolution matrix that is independent of atomic velocity
        "A_dop", # Part of density-matrix evolution matrix describing Doppler shift
        "A_rec", # Part of density-matrix evolution matrix describing atomic recoil
        "A_vcc", # Part of density-matrix evolution matrix describing velocity-changing collisions
        "b", # Constant vector in the density-matrix evolution equation describing atomic transit
        "Flux" # Operator giving return flux from each transition
    ]
    
    def __init__(
        self, 
        system:str, # Name of the atomic system to be loaded from file
        fixed_params:dict={} # Values for system parameters that will be held fixed
    ):
        self.path = LGSSystem._get_path(system)
        fixed_params = Mu(fixed_params)
        self.__auto_init(locals())
        for name in self.block_names:
            setattr(
                self, 
                name,
                LincombOperator.from_file(self.path/name).partial_assemble(self.fixed_params).with_(name=name)
            )
        self.Flux = XarrayMatrixOperator(self.Flux.matrix.rename({"Transition": "Transition (range)"}))
        self.parameters = Parameters.of(*(getattr(self, name) for name in self.block_names))
        self.initial = LincombOperator.from_file(self.path/'b').partial_assemble(Mu(BeamTransitRatePerS=1)).as_range_array()
        # self.initial = self.Flux.source.from_xarray(
        #     LincombOperator.from_file(self.path/'b').partial_assemble(Mu(BeamTransitRatePerS=1)).matrix.rename({'Density matrix (range)': 'Density matrix (source)'})
        # )
        self.n_variables = self.Flux.source.dim 
        self.dm_elements = self.Flux.assemble().matrix['Density matrix' + Lbl.SRC].rename({"Density matrix (source)": "Density matrix"})
        self.level_population = level_population(self.dm_elements)
        self.population = population(self.dm_elements) 
        self.total_population = total_population(self.dm_elements)

