@patch
def stationary_model(
    self:LGSSystem, 
    vg:int|Iterable|VelocityGroups=6, # Specification of velocity groups 
    # output='total_flux' # Operator to be applied to solution to obtain the output
    solver:Solver|dict|None=None,
) -> StationaryModel: # Model for the steady-state LGS system
    """Return a pyMOR `StationaryModel` for the steady state cw LGS system."""
    vg = VelocityGroups(vg)
    if solver is None: solver = {}
    if isinstance(solver, dict):
        # solver = {'preconditioner': -self._reaction(vg), 'preconditioner_block_size': self.Flux.source.size} | solver
        default_solver = dict(
            spilu_fill_factor=50,
            spilu_drop_tol=1e-3,
            rtol=1e-3,
            atol=1e-3,
            preconditioner_block_size=self.Flux.source.size
        )
        solver = ScipyGCROTMKSpILUSolver(**(default_solver | solver))
    return StationaryModel(
        self.operator(vg).with_(solver=solver),
        self.rhs(vg), 
        products=self._products(vg),
        data={
            'velocity_groups': vg,
            'grid': OnedUnstructuredGrid(vg.edges)
        }
    )

# %% ../nbs/api/lgssystem.ipynb #ab273296
def vg_to_refine(flux:DataArray, rtol:float=1e-2, fraction:float=0.15):
    fine_vg = np.union1d(flux.v, flux.v.rolling(v=2).mean()[1:])
    coarse_int = xsi.cumulative_trapezoid(flux, 'v')
    fine_int = xsi.cumulative_simpson(flux.interp(v=fine_vg, method='akima').fillna(0), 'v').sel(v=flux.v)
    dims = [d for d in flux.dims if d != 'v']
    int_err = abs((fine_int - coarse_int).diff('v').sum(dims).squeeze())
    global_err = int_err.sum('v').sum().item()/fine_int.isel(v=-1).sum().item()
    logger.info(f"Model with {len(flux.v)} velocity groups gives coarse_int={coarse_int.isel(v=-1).sum().item()}, fine_int={fine_int.isel(v=-1).sum().item()}, fractional error {global_err:.2e}")
    if global_err < rtol: return []
    num_to_refine = max(1, int(len(int_err.v) * fraction))
    new_edges = int_err.sortby(int_err, ascending=False)[:num_to_refine].v
    return new_edges

# %% ../nbs/api/lgssystem.ipynb #24f80def
@patch
def adaptive_stationary_model(
    self:LGSSystem, 
    mu, # Parameter values to use during velocity-group refinement
    vg=6, # Initial velocity groups
    solver=None, # Solver to use for the linear system
    rtol=2e-3, # Global error tolerance for the return flux integral
    refine_fraction=0.4, # Fraction of velocity groups to refine at each iteration
)->StationaryModel: # Steady-state LGS model with more velocity groups in regions that produce more return flux
    """Create a `StationaryModel` with narrower velocity bins in velocity regions with higher flux."""
    model = self.stationary_model(vg=vg, solver=solver)
    sol = model.solve(mu)
    flux = model.flux_distribution(sol).array.rename('flux').rename({'Atomic velocity': 'v'})
    while True:
        new_edges = vg_to_refine(flux, rtol=rtol, fraction=refine_fraction)
        if len(new_edges) == 0: break
        vg = VelocityGroups(np.union1d(model.data['velocity_groups'].edges, new_edges))
        model = self.stationary_model(vg=vg, solver=solver)
        sol = model.solve(mu)
        flux = model.flux_distribution(sol).array.rename('flux').rename({'Atomic velocity': 'v'})
    return model, sol

