# %% ../nbs/api/lgssystem.ipynb #1b34e706
def _to_nmo(op, format='dense'):
    return NumpyMatrixOperator(to_matrix(op, format=format))

# %% ../nbs/api/lgssystem.ipynb #6a43e9e2
@patch
@delegates(LGSSystem.instationary_model)
def numpy_instationary_model(self:LGSSystem, vg, **kwargs):
    model = self.instationary_model(vg, **kwargs)
    operator = expand(model.operator)
    operator = contract(LincombOperator([_to_nmo(o) for o in operator.operators], operator.coefficients))
    rhs = _to_nmo(model.rhs)
    initial_data = _to_nmo(model.initial_data)
    vg = model.data['velocity_groups']
    # vg_sum = XarrayMatrixOperator(np.ones([1, vg['VGNumber']]), source=vg.sum().source, range=vg.sum().range)
    output_functional = _to_nmo(IdentityOperator(vg.sum().source) * model.products['flux'])
    return InstationaryModel(
        T=model.T,
        initial_data=initial_data,
        operator=operator,
        rhs=rhs,
        output_functional=output_functional,
        mass=None,
        time_stepper=model.time_stepper,
        num_values=model.num_values,
        products=None,
        error_estimator=None,
        visualizer=None,
        name=None,
    )

