@patch
def stationary_floquet_model(
    self:LGSSystem, 
    mu, # Parameter specification for parameters modulated at a frequency `nu` 
    time, # List of time values to use for reconstruction
    n_vector, # Number of terms in the system Fourier series
    nu:str='nu', # Name of the frequency variable
    n_operator=None, # Number of terms in the operator Fourier series. `None` defaults to `n_vector` - 1
    vg:int|Iterable|VelocityGroups=6, # Specification of velocity groups
    solver=None,
    preconditioner=None,
) -> StationaryFloquetModel: # Model for the Fourier coefficients of the periodic LGS system
    """Return a `StationaryFloquetModel` for the Fourier coefficients of the periodic state of a modulated LGS system."""
    vg = VelocityGroups(vg)
    if solver is None: solver = {}
    if isinstance(solver, dict):
        default_solver = dict(
            spilu_fill_factor=50,
            spilu_drop_tol=1e-3,
            rtol=1e-3,
            atol=1e-3,
            preconditioner_block_size=self.Flux.source.size
        )
        solver = ScipyGCROTMKSpILUSolver(**(default_solver | solver))
    return StationaryFloquetModel(
        operator=expand(self.operator(vg)),
        rhs=self.rhs(vg), 
        mu=mu,
        nu=nu,
        time=time,
        n_vector=n_vector,
        n_operator=n_operator,
        products=self._products(vg) | self._floquet_products(vg, n_vector, time),
        data={
            'velocity_groups': vg,
            'grid': OnedUnstructuredGrid(vg.edges)
        },
        solver=solver,
        preconditioner=preconditioner # or -self._reaction(vg),
    )

# %% ../nbs/api/lgssystem.ipynb #753fad8e
@patch
def adaptive_stationary_floquet_model(
    self:LGSSystem, 
    mu, # Parameter specification for parameters modulated at a frequency `nu`
    time, # List of time values to use for reconstruction
    n_vector, # Number of terms in the system Fourier series
    mu_refine=None, # Additional parameter specifications used during velocity-group refinement
    nu:str='nu', # Name of the frequency variable
    n_operator=None, # Number of terms in the operator Fourier series. `None` defaults to `n_vector` - 1
    vg=6, # Initial (number of) velocity groups
    solver=None, # Steady-state solver or options for the default solver
    rtol=2e-3, # Global error tolerance for the return flux integral
    refine_fraction=0.4, # Fraction of velocity groups to refine at each iteration
)->StationaryFloquetModel: # Steady-state LGS model with more velocity groups in regions that produce more return flux
    """Create a `StationaryModel` with narrower velocity bins in velocity regions with higher flux."""
    vg = VelocityGroups(vg)
    logger.info(f'Creating and solving model with {vg["VGNumber"]} velocity groups')
    tic = clock()
    model = self.stationary_floquet_model(mu, time, n_vector, nu=nu, n_operator=n_operator, vg=vg, solver=solver)
    toc = clock()
    sol = model.solve(mu_refine)
    logger.info(f'Model created in {toc - tic:.2f} seconds, solved in {clock() - toc:.2f} seconds')
    flux = model.reconstructed_flux(sol, mu_refine).real.array.rename('flux').rename({'Atomic velocity': 'v'}).sum(['Time', 'Transition']).squeeze()
    while True:
        new_edges = vg_to_refine(flux, rtol=rtol, fraction=refine_fraction)
        if len(new_edges) == 0: break
        vg = VelocityGroups(np.union1d(model.data['velocity_groups'].edges, new_edges))
        logger.info(f'Refining model to {vg["VGNumber"]} velocity groups')
        model = self.stationary_floquet_model(mu, time, n_vector, nu=nu, n_operator=n_operator, vg=vg, solver=solver)
        sol = model.solve(mu_refine)
        flux = model.reconstructed_flux(sol, mu_refine).real.array.rename('flux').rename({'Atomic velocity': 'v'}).sum(['Time', 'Transition']).squeeze()
    return model, sol
